contract InvMutTest
{
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function test(uint256 _val) public
    { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 2 ether, "need funds");
        c.SetMinSum(_val); if (__ESBMC_reverted()) return;
        assert(c.MinSum() == _val);
    }

    receive() external payable {}
    fallback() external payable {}
}

